    address token,
    uint104 amount,
    bool expectRevert,
    uint256 oldStakedAmount,
    uint256 oldCoolingDownAmount,
    uint256 oldCooldownStartTimestamp,
    uint256 oldTotalStaked,
    uint256 oldTotalCoolingDown
  ) internal {
    if (!expectRevert) {
      vm.expectEmit(true, true, true, true);
      emit Stake(caller, token, amount);
