        token,
        oldStakedAmount,
        oldCoolingDownAmount,
        oldCooldownStartTimestamp,
        oldTotalStaked,
        oldTotalCoolingDown
      );
    } else {
      _checkStake(
        caller,
        token,
        oldStakedAmount - amount,
        oldCoolingDownAmount + amount,
        block.timestamp,
        oldTotalStaked - amount,
        oldTotalCoolingDown + amount
      );
    }
  }

  function _withdrawAndCheck(
    address caller,
