      // 1e-16 percent is the max chg https://book.getfoundry.sh/reference/forge-std/assertApproxEqRel
      assertApproxEqRel(newRate, prevRate, 1, "_redeem: Rate should not change");
    }

    vm.warp(cooldownEnd + 1);

